SELECT 
    ROUND(
        (SELECT COUNT(*) FROM VUL_001 WHERE hex_id IN (SELECT hex_id FROM hex_county_state_zip_crosswalk WHERE "County" = 'Cameron') AND "sovi" IS NOT NULL) * 1.0 
        / (SELECT COUNT(*) FROM hex_county_state_zip_crosswalk WHERE "County" = 'Cameron'), 
        4
    ) AS coverage_fraction;

SELECT DISTINCT "hex_id" 
FROM "hex_county_state_zip_crosswalk" 
WHERE "County" = 'Montgomery County';
